CREATE TABLE hubspot_synced_contacts (
  hubspot_contact_id TEXT PRIMARY KEY,
  email TEXT NOT NULL,
  first_name TEXT,
  last_name TEXT,
  company TEXT,
  lifecycle_stage TEXT,
  sequence_memberships JSONB NOT NULL DEFAULT '[]'::jsonb, -- which sequences they're enrolled in
