-- ############################################################
-- 012_recurrence_builder.sql
-- ############################################################
-- ============================================================
-- Migration 012: Google-Calendar-style recurrence
-- Adds "repeat every N day/week/month", specific weekdays for weekly
-- recurrence, and an explicit end condition (never / on date / after N
-- occurrences) to recurring_templates. The old pattern/custom_interval_days/
-- ends_on columns are kept (still NOT NULL) and are written as a best-fit
-- label for backward compatibility, but are no longer used for date math.
-- Idempotent. Safe to re-run. PASTE INTO SUPABASE SQL EDITOR.
-- ============================================================

ALTER TABLE recurring_templates
  ADD COLUMN IF NOT EXISTS interval_count INT NOT NULL DEFAULT 1,
  ADD COLUMN IF NOT EXISTS interval_unit TEXT NOT NULL DEFAULT 'week',
  ADD COLUMN IF NOT EXISTS by_weekdays SMALLINT[],
  ADD COLUMN IF NOT EXISTS end_type TEXT NOT NULL DEFAULT 'never',
  ADD COLUMN IF NOT EXISTS occurrences_total INT,
  ADD COLUMN IF NOT EXISTS occurrences_done INT NOT NULL DEFAULT 1;

ALTER TABLE recurring_templates DROP CONSTRAINT IF EXISTS recurring_templates_interval_unit_check;
ALTER TABLE recurring_templates ADD CONSTRAINT recurring_templates_interval_unit_check
  CHECK (interval_unit IN ('day', 'week', 'month'));

ALTER TABLE recurring_templates DROP CONSTRAINT IF EXISTS recurring_templates_end_type_check;
ALTER TABLE recurring_templates ADD CONSTRAINT recurring_templates_end_type_check
  CHECK (end_type IN ('never', 'on_date', 'after_count'));

ALTER TABLE recurring_templates DROP CONSTRAINT IF EXISTS recurring_templates_interval_count_check;
ALTER TABLE recurring_templates ADD CONSTRAINT recurring_templates_interval_count_check
  CHECK (interval_count >= 1);

-- Backfill existing rows from the legacy pattern so already-recurring tasks
-- keep advancing on the same schedule under the new engine.
UPDATE recurring_templates SET
  interval_count = CASE pattern
    WHEN 'daily' THEN 1
    WHEN 'weekly' THEN 1
    WHEN 'biweekly' THEN 2
    WHEN 'monthly' THEN 1
    WHEN 'custom' THEN GREATEST(1, COALESCE(custom_interval_days, 7))
    ELSE 1
  END,
  interval_unit = CASE pattern
    WHEN 'daily' THEN 'day'
    WHEN 'weekly' THEN 'week'
    WHEN 'biweekly' THEN 'week'
    WHEN 'monthly' THEN 'month'
    WHEN 'custom' THEN 'day'
    ELSE 'week'
  END,
  end_type = CASE WHEN ends_on IS NOT NULL THEN 'on_date' ELSE 'never' END
WHERE interval_count = 1 AND interval_unit = 'week' AND end_type = 'never';
-- (the WHERE guards against re-stamping rows already migrated or created
-- fresh under the new engine on a re-run)

-- ############################################################
-- 013_weekly_reports.sql
-- ############################################################
-- ============================================================
-- Migration 013: Weekly Report generator
-- Backs the "Create Weekly Report" button on /weekly: a manual ad-spend
-- ledger (no ads-platform integration exists yet), free-form "done" items
-- that do NOT create real tasks, and the generated report HTML itself,
-- keyed by ISO week_starting (Monday) to match weekly_snapshots.
-- Idempotent. Safe to re-run. PASTE INTO SUPABASE SQL EDITOR.
-- ============================================================

CREATE TABLE IF NOT EXISTS report_ad_spend (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  week_starting DATE NOT NULL,
  platform TEXT NOT NULL,
  campaign TEXT,
  spend NUMERIC(12,2) NOT NULL DEFAULT 0,
  leads INT,
  notes TEXT,
  added_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS report_ad_spend_week_idx ON report_ad_spend(week_starting);

-- Free-form "task / subtask done" bullets for the report only — explicitly
-- NOT rows in the `tasks` table, so they never appear on any tracker board.
CREATE TABLE IF NOT EXISTS report_done_items (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  week_starting DATE NOT NULL,
  task_title TEXT NOT NULL,
  subtask_title TEXT,
  sort_order INT NOT NULL DEFAULT 0,
  added_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE INDEX IF NOT EXISTS report_done_items_week_idx ON report_done_items(week_starting);

-- The generated report itself. "Create Weekly Report" upserts this row for
-- the selected date range; `summary` keeps the structured inputs so the
-- report can be regenerated/edited later without re-deriving everything.
-- Reports can now cover a custom (non-week-aligned) range, so the natural
-- key is the (start, end) pair rather than start alone.
CREATE TABLE IF NOT EXISTS weekly_reports (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  week_starting DATE NOT NULL,
  week_ending DATE NOT NULL,
  html TEXT NOT NULL,
  summary JSONB NOT NULL DEFAULT '{}'::jsonb,
  generated_by UUID REFERENCES users(id) ON DELETE SET NULL,
  generated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (week_starting, week_ending)
);

ALTER TABLE report_ad_spend   ENABLE ROW LEVEL SECURITY;
ALTER TABLE report_done_items ENABLE ROW LEVEL SECURITY;
ALTER TABLE weekly_reports    ENABLE ROW LEVEL SECURITY;

DROP POLICY IF EXISTS "report_ad_spend_read"  ON report_ad_spend;
DROP POLICY IF EXISTS "report_ad_spend_write" ON report_ad_spend;
CREATE POLICY "report_ad_spend_read"  ON report_ad_spend FOR SELECT TO authenticated USING (true);
CREATE POLICY "report_ad_spend_write" ON report_ad_spend FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "report_done_items_read"  ON report_done_items;
DROP POLICY IF EXISTS "report_done_items_write" ON report_done_items;
CREATE POLICY "report_done_items_read"  ON report_done_items FOR SELECT TO authenticated USING (true);
CREATE POLICY "report_done_items_write" ON report_done_items FOR ALL TO authenticated USING (true) WITH CHECK (true);

DROP POLICY IF EXISTS "weekly_reports_read"  ON weekly_reports;
DROP POLICY IF EXISTS "weekly_reports_write" ON weekly_reports;
CREATE POLICY "weekly_reports_read"  ON weekly_reports FOR SELECT TO authenticated USING (true);
CREATE POLICY "weekly_reports_write" ON weekly_reports FOR ALL TO authenticated USING (true) WITH CHECK (true);

GRANT ALL ON report_ad_spend, report_done_items, weekly_reports TO authenticated, service_role;

-- ############################################################
-- 014_verticals_and_functions.sql
-- ############################################################
-- ============================================================
-- Migration 014: Verticals + Functions
-- Turns the single-business-unit GSI tracker into a multi-vertical
-- workspace ("Lyzr Marketing Tracker"):
--   verticals            top level above categories (GSI, Emerging Partners,
--                        per-product verticals, and "Lyzr" company-wide)
--   vertical_owners      who manages a vertical (by email, resolved on sign-in)
--   functions            workspace-wide channel functions (Content, Social...)
--                        so the same function rolls up across verticals
--   function_owners      default owners inherited by every vertical's instance
--   vertical_resources   per-vertical link groups (replaces hardcoded page)
-- Categories get vertical_id; channels get a denormalised vertical_id (kept
-- in sync by trigger) and function_id. Budgets/reports/snapshots/saved views
-- are scoped by vertical. Idempotent; paste into the SQL Editor or replay via
-- RESET_ALL.sql.
--
-- ENUM GOTCHA: budget_scope_type gains 'vertical' below. Nothing in THIS file
-- may reference that literal (PG forbids using a new enum value in the same
-- transaction). Triggers compare scope_type::text instead.
-- ============================================================

-- ---------- 1. verticals ----------
CREATE TABLE IF NOT EXISTS verticals (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  description TEXT,
  icon TEXT,
  color TEXT,
  sort_order INT NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  -- feature flags: {leads_pipeline, weekly_report_builder, resources, hubspot_contacts}
  settings JSONB NOT NULL DEFAULT '{"leads_pipeline":false,"weekly_report_builder":false,"resources":false,"hubspot_contacts":false}'::jsonb,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

DROP TRIGGER IF EXISTS verticals_updated_at ON verticals;
CREATE TRIGGER verticals_updated_at BEFORE UPDATE ON verticals
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- ---------- 2. vertical owners (mirror of channel_owners) ----------
CREATE TABLE IF NOT EXISTS vertical_owners (
  vertical_id UUID NOT NULL REFERENCES verticals(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (vertical_id, email)
);
CREATE INDEX IF NOT EXISTS vertical_owners_email_idx ON vertical_owners(email);
CREATE INDEX IF NOT EXISTS vertical_owners_user_idx  ON vertical_owners(user_id);

-- ---------- 3. functions + function owners ----------
CREATE TABLE IF NOT EXISTS functions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  icon TEXT,
  sort_order INT NOT NULL DEFAULT 0,
  is_active BOOLEAN NOT NULL DEFAULT TRUE,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

CREATE TABLE IF NOT EXISTS function_owners (
  function_id UUID NOT NULL REFERENCES functions(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (function_id, email)
);
CREATE INDEX IF NOT EXISTS function_owners_email_idx ON function_owners(email);
CREATE INDEX IF NOT EXISTS function_owners_user_idx  ON function_owners(user_id);

INSERT INTO functions (name, slug, icon, sort_order) VALUES
  ('Paid',         'paid',         'zap',        1),
  ('Outbound',     'outbound',     'send',       2),
  ('Content',      'content',      'file-text',  3),
  ('Social',       'social',       'share-2',    4),
  ('Events',       'events',       'calendar',   5),
  ('Community',    'community',    'users',      6),
  ('Partnerships', 'partnerships', 'handshake',  7),
  ('ABM',          'abm',          'target',     8),
  ('BTL',          'btl',          'megaphone',  9),
  ('Referrals',    'referrals',    'gift',      10),
  ('Website',      'website',      'globe',     11),
  ('Analyst / PR', 'analyst-pr',   'newspaper', 12)
ON CONFLICT (slug) DO NOTHING;

-- ---------- 4. categories -> vertical; slug unique PER vertical ----------
ALTER TABLE categories ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE RESTRICT;
-- Live-DB safety (no-op on a fresh reset): park orphans in a GSI vertical.
DO $$
BEGIN
  IF EXISTS (SELECT 1 FROM categories WHERE vertical_id IS NULL) THEN
    INSERT INTO verticals (name, slug, sort_order, settings)
    VALUES ('GSI', 'gsi', 1, '{"leads_pipeline":true,"weekly_report_builder":true,"resources":true,"hubspot_contacts":true}'::jsonb)
    ON CONFLICT (slug) DO NOTHING;
    UPDATE categories SET vertical_id = (SELECT id FROM verticals WHERE slug = 'gsi') WHERE vertical_id IS NULL;
  END IF;
END $$;
ALTER TABLE categories ALTER COLUMN vertical_id SET NOT NULL;
ALTER TABLE categories DROP CONSTRAINT IF EXISTS categories_slug_key;
CREATE UNIQUE INDEX IF NOT EXISTS categories_vertical_slug_uq ON categories(vertical_id, slug);
CREATE INDEX IF NOT EXISTS categories_vertical_idx ON categories(vertical_id);

-- ---------- 5. channels -> vertical (denormalised) + function ----------
ALTER TABLE channels ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE RESTRICT;
ALTER TABLE channels ADD COLUMN IF NOT EXISTS function_id UUID REFERENCES functions(id) ON DELETE SET NULL;
UPDATE channels ch SET vertical_id = c.vertical_id
  FROM categories c WHERE c.id = ch.category_id AND ch.vertical_id IS NULL;
ALTER TABLE channels ALTER COLUMN vertical_id SET NOT NULL;
CREATE INDEX IF NOT EXISTS channels_vertical_idx ON channels(vertical_id);
CREATE INDEX IF NOT EXISTS channels_function_idx ON channels(function_id);

-- Close the NULL-parent hole: UNIQUE(category_id, parent_channel_id, slug)
-- treats NULL parents as distinct, so two top-level channels could share a
-- slug in one category. Replace with a COALESCE'd unique index.
ALTER TABLE channels DROP CONSTRAINT IF EXISTS channels_category_id_parent_channel_id_slug_key;
CREATE UNIQUE INDEX IF NOT EXISTS channels_slug_uq
  ON channels (category_id, COALESCE(parent_channel_id, '00000000-0000-0000-0000-000000000000'::uuid), slug);

-- Keep channels.vertical_id honest and forbid a parent in another category.
CREATE OR REPLACE FUNCTION channels_sync_vertical()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
DECLARE cat_v UUID; par_cat UUID; par_fn UUID;
BEGIN
  SELECT vertical_id INTO cat_v FROM categories WHERE id = NEW.category_id;
  IF cat_v IS NULL THEN
    RAISE EXCEPTION 'category % not found', NEW.category_id;
  END IF;
  NEW.vertical_id := cat_v;
  IF NEW.parent_channel_id IS NOT NULL THEN
    SELECT category_id, function_id INTO par_cat, par_fn FROM channels WHERE id = NEW.parent_channel_id;
    IF par_cat IS DISTINCT FROM NEW.category_id THEN
      RAISE EXCEPTION 'parent channel % is in a different category', NEW.parent_channel_id;
    END IF;
    -- Sub-channels inherit the parent's function unless set explicitly.
    IF NEW.function_id IS NULL THEN NEW.function_id := par_fn; END IF;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS channels_sync_vertical_trg ON channels;
CREATE TRIGGER channels_sync_vertical_trg
  BEFORE INSERT OR UPDATE OF category_id, parent_channel_id, function_id ON channels
  FOR EACH ROW EXECUTE FUNCTION channels_sync_vertical();

-- A category cannot move between verticals once it has channels.
CREATE OR REPLACE FUNCTION categories_guard_vertical_move()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.vertical_id IS DISTINCT FROM OLD.vertical_id
     AND EXISTS (SELECT 1 FROM channels WHERE category_id = NEW.id) THEN
    RAISE EXCEPTION 'category % has channels; it cannot move to another vertical', NEW.id;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS categories_guard_vertical_move_trg ON categories;
CREATE TRIGGER categories_guard_vertical_move_trg
  BEFORE UPDATE OF vertical_id ON categories
  FOR EACH ROW EXECUTE FUNCTION categories_guard_vertical_move();

-- ---------- 6. vertical resources ----------
CREATE TABLE IF NOT EXISTS vertical_resources (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vertical_id UUID NOT NULL REFERENCES verticals(id) ON DELETE CASCADE,
  group_name TEXT NOT NULL,
  name TEXT NOT NULL,
  url TEXT NOT NULL,
  sort_order INT NOT NULL DEFAULT 0,
  added_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS vertical_resources_vertical_idx ON vertical_resources(vertical_id);

-- ---------- 7. vertical scope on budgets / reports / snapshots / views ----------
ALTER TYPE budget_scope_type ADD VALUE IF NOT EXISTS 'vertical';

ALTER TABLE budget_periods    ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE; -- NULL = workspace/global
ALTER TABLE weekly_reports    ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;
ALTER TABLE report_ad_spend   ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;
ALTER TABLE report_done_items ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;
ALTER TABLE weekly_snapshots  ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;
ALTER TABLE saved_views       ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;
ALTER TABLE slack_settings    ADD COLUMN IF NOT EXISTS vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE;

-- Reports and snapshots are always per vertical (the "Lyzr" vertical is the
-- company-wide scope). Backfill orphans into GSI, then require it.
DO $$
DECLARE gsi UUID;
BEGIN
  SELECT id INTO gsi FROM verticals WHERE slug = 'gsi';
  IF gsi IS NOT NULL THEN
    UPDATE weekly_reports    SET vertical_id = gsi WHERE vertical_id IS NULL;
    UPDATE report_ad_spend   SET vertical_id = gsi WHERE vertical_id IS NULL;
    UPDATE report_done_items SET vertical_id = gsi WHERE vertical_id IS NULL;
    UPDATE weekly_snapshots  SET vertical_id = gsi WHERE vertical_id IS NULL;
  END IF;
  -- On a fresh reset these tables are empty, so NOT NULL is safe either way.
  IF NOT EXISTS (SELECT 1 FROM weekly_reports WHERE vertical_id IS NULL)
     AND NOT EXISTS (SELECT 1 FROM report_ad_spend WHERE vertical_id IS NULL)
     AND NOT EXISTS (SELECT 1 FROM report_done_items WHERE vertical_id IS NULL)
     AND NOT EXISTS (SELECT 1 FROM weekly_snapshots WHERE vertical_id IS NULL) THEN
    ALTER TABLE weekly_reports    ALTER COLUMN vertical_id SET NOT NULL;
    ALTER TABLE report_ad_spend   ALTER COLUMN vertical_id SET NOT NULL;
    ALTER TABLE report_done_items ALTER COLUMN vertical_id SET NOT NULL;
    ALTER TABLE weekly_snapshots  ALTER COLUMN vertical_id SET NOT NULL;
  END IF;
END $$;

ALTER TABLE weekly_reports   DROP CONSTRAINT IF EXISTS weekly_reports_week_starting_week_ending_key;
ALTER TABLE weekly_reports   DROP CONSTRAINT IF EXISTS weekly_reports_vertical_week_uq;
ALTER TABLE weekly_reports   ADD  CONSTRAINT weekly_reports_vertical_week_uq UNIQUE (vertical_id, week_starting, week_ending);

ALTER TABLE weekly_snapshots DROP CONSTRAINT IF EXISTS weekly_snapshots_week_starting_key;
ALTER TABLE weekly_snapshots DROP CONSTRAINT IF EXISTS weekly_snapshots_vertical_week_uq;
ALTER TABLE weekly_snapshots ADD  CONSTRAINT weekly_snapshots_vertical_week_uq UNIQUE (vertical_id, week_starting);

-- Saved views: NULL vertical = a workspace-level ("all verticals") view.
ALTER TABLE saved_views DROP CONSTRAINT IF EXISTS saved_views_user_id_page_name_key;
CREATE UNIQUE INDEX IF NOT EXISTS saved_views_uq
  ON saved_views (user_id, page, COALESCE(vertical_id, '00000000-0000-0000-0000-000000000000'::uuid), name);

CREATE INDEX IF NOT EXISTS report_ad_spend_vertical_week_idx   ON report_ad_spend(vertical_id, week_starting);
CREATE INDEX IF NOT EXISTS report_done_items_vertical_week_idx ON report_done_items(vertical_id, week_starting);
CREATE INDEX IF NOT EXISTS budget_periods_vertical_idx         ON budget_periods(vertical_id);

-- budget_periods.vertical_id derived from the scope (global = NULL).
CREATE OR REPLACE FUNCTION budget_periods_sync_vertical()
RETURNS TRIGGER LANGUAGE plpgsql AS $$
BEGIN
  IF NEW.scope_type::text = 'vertical' THEN
    NEW.vertical_id := NEW.scope_id;
  ELSIF NEW.scope_type::text = 'category' THEN
    SELECT vertical_id INTO NEW.vertical_id FROM categories WHERE id = NEW.scope_id;
  ELSIF NEW.scope_type::text = 'channel' THEN
    SELECT vertical_id INTO NEW.vertical_id FROM channels WHERE id = NEW.scope_id;
  ELSE
    NEW.vertical_id := NULL;
  END IF;
  RETURN NEW;
END $$;
DROP TRIGGER IF EXISTS budget_periods_sync_vertical_trg ON budget_periods;
CREATE TRIGGER budget_periods_sync_vertical_trg BEFORE INSERT OR UPDATE ON budget_periods
  FOR EACH ROW EXECUTE FUNCTION budget_periods_sync_vertical();

-- Backfill vertical_id on existing budget rows (no-op on fresh reset).
UPDATE budget_periods bp SET vertical_id = c.vertical_id
  FROM categories c WHERE bp.scope_type::text = 'category' AND c.id = bp.scope_id AND bp.vertical_id IS NULL;
UPDATE budget_periods bp SET vertical_id = ch.vertical_id
  FROM channels ch WHERE bp.scope_type::text = 'channel' AND ch.id = bp.scope_id AND bp.vertical_id IS NULL;

-- budget_period_summary gains vertical_id (same leading columns, so REPLACE works).
CREATE OR REPLACE VIEW budget_period_summary AS
SELECT
  bp.id AS budget_period_id,
  bp.period_label,
  bp.scope_type,
  bp.scope_id,
  bp.total_budget,
  COALESCE(SUM(t.budget_allocated), 0) AS allocated,
  bp.total_budget - COALESCE(SUM(t.budget_allocated), 0) AS remaining,
  COUNT(t.id) FILTER (WHERE t.budget_allocated IS NOT NULL) AS task_count,
  bp.vertical_id
FROM budget_periods bp
LEFT JOIN tasks t ON t.budget_period_id = bp.id
GROUP BY bp.id;

-- ---------- 8. effective channel owners ----------
-- Explicit channel_owners rows win; otherwise the channel inherits the
-- owners of its function. Sub-channels with no rows of their own fall back
-- to their parent channel's rows before the function.
CREATE OR REPLACE VIEW effective_channel_owners AS
SELECT ch.id AS channel_id, co.email, co.user_id, co.sort_order, 'channel'::text AS source
  FROM channels ch
  JOIN channel_owners co ON co.channel_id = ch.id
UNION ALL
SELECT ch.id, pco.email, pco.user_id, pco.sort_order, 'parent'::text
  FROM channels ch
  JOIN channel_owners pco ON pco.channel_id = ch.parent_channel_id
 WHERE NOT EXISTS (SELECT 1 FROM channel_owners x WHERE x.channel_id = ch.id)
UNION ALL
SELECT ch.id, fo.email, fo.user_id, fo.sort_order, 'function'::text
  FROM channels ch
  JOIN function_owners fo ON fo.function_id = ch.function_id
 WHERE NOT EXISTS (SELECT 1 FROM channel_owners x WHERE x.channel_id = ch.id)
   AND NOT EXISTS (SELECT 1 FROM channel_owners p WHERE p.channel_id = ch.parent_channel_id);

-- ---------- 9. handle_new_user: full 010 body + vertical/function owner linking ----------
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    CASE WHEN NEW.email = 'kailash.gm@lyzr.ai' THEN 'admin'::user_role ELSE 'member'::user_role END
  );

  UPDATE pending_mentions
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id
    FROM pending_mentions pm
   WHERE pm.email = NEW.email AND pm.resolved_user_id = NEW.id;

  UPDATE pending_invites
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE
           WHEN pa.role = 'primary' AND EXISTS (
             SELECT 1 FROM task_assignments ta
              WHERE ta.task_id = pa.task_id AND ta.role = 'primary'
           ) THEN 'secondary'::assignment_role
           ELSE pa.role
         END,
         pa.assigned_by
    FROM pending_assignments pa
   WHERE pa.email = NEW.email AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;

  UPDATE pending_assignments
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  UPDATE channel_owners
     SET user_id = NEW.id
   WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;

  -- NEW (014): vertical + function ownership seeded by email
  UPDATE vertical_owners
     SET user_id = NEW.id
   WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;

  UPDATE function_owners
     SET user_id = NEW.id
   WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;

  RETURN NEW;
END;
$$;

-- ---------- 10. grants ----------
GRANT ALL ON verticals, vertical_owners, functions, function_owners, vertical_resources TO authenticated, service_role;
GRANT SELECT ON effective_channel_owners, budget_period_summary TO authenticated, service_role;

-- ############################################################
-- 015_verticals_rls.sql
-- ############################################################
-- ============================================================
-- Migration 015: RLS for verticals
-- Reads stay open to every signed-in user. Structural writes move from
-- "global admin only" to "admin OR owner of that row's vertical".
-- Tasks / assignments / checklists / comments are untouched (any member).
-- Idempotent.
-- ============================================================

-- ---------- helpers ----------
CREATE OR REPLACE FUNCTION public.is_service_role()
RETURNS BOOLEAN LANGUAGE sql STABLE AS $$
  SELECT COALESCE(auth.role() = 'service_role', false);
$$;

CREATE OR REPLACE FUNCTION public.is_vertical_owner(v UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (
    SELECT 1 FROM vertical_owners WHERE vertical_id = v AND user_id = auth.uid()
  );
$$;

CREATE OR REPLACE FUNCTION public.can_manage_vertical(v UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT is_admin() OR is_service_role() OR (v IS NOT NULL AND is_vertical_owner(v));
$$;

CREATE OR REPLACE FUNCTION public.category_vertical(c UUID)
RETURNS UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT vertical_id FROM categories WHERE id = c;
$$;

CREATE OR REPLACE FUNCTION public.channel_vertical(c UUID)
RETURNS UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT vertical_id FROM channels WHERE id = c;
$$;

CREATE OR REPLACE FUNCTION public.my_vertical_ids()
RETURNS SETOF UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT vertical_id FROM vertical_owners WHERE user_id = auth.uid();
$$;

GRANT EXECUTE ON FUNCTION public.is_service_role()        TO authenticated, anon, service_role;
GRANT EXECUTE ON FUNCTION public.is_vertical_owner(UUID)  TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_manage_vertical(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.category_vertical(UUID)  TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.channel_vertical(UUID)   TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.my_vertical_ids()        TO authenticated, service_role;

-- ---------- verticals ----------
ALTER TABLE verticals ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "verticals_read"   ON verticals;
DROP POLICY IF EXISTS "verticals_insert" ON verticals;
DROP POLICY IF EXISTS "verticals_update" ON verticals;
DROP POLICY IF EXISTS "verticals_delete" ON verticals;
CREATE POLICY "verticals_read"   ON verticals FOR SELECT TO authenticated USING (true);
CREATE POLICY "verticals_insert" ON verticals FOR INSERT TO authenticated WITH CHECK (is_admin());
CREATE POLICY "verticals_update" ON verticals FOR UPDATE TO authenticated
  USING (can_manage_vertical(id)) WITH CHECK (can_manage_vertical(id));
CREATE POLICY "verticals_delete" ON verticals FOR DELETE TO authenticated USING (is_admin());

-- ---------- vertical_owners / functions / function_owners: admin ----------
ALTER TABLE vertical_owners ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "vertical_owners_read"  ON vertical_owners;
DROP POLICY IF EXISTS "vertical_owners_write" ON vertical_owners;
CREATE POLICY "vertical_owners_read"  ON vertical_owners FOR SELECT TO authenticated USING (true);
CREATE POLICY "vertical_owners_write" ON vertical_owners FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

ALTER TABLE functions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "functions_read"  ON functions;
DROP POLICY IF EXISTS "functions_write" ON functions;
CREATE POLICY "functions_read"  ON functions FOR SELECT TO authenticated USING (true);
CREATE POLICY "functions_write" ON functions FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

ALTER TABLE function_owners ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "function_owners_read"  ON function_owners;
DROP POLICY IF EXISTS "function_owners_write" ON function_owners;
CREATE POLICY "function_owners_read"  ON function_owners FOR SELECT TO authenticated USING (true);
CREATE POLICY "function_owners_write" ON function_owners FOR ALL TO authenticated
  USING (is_admin()) WITH CHECK (is_admin());

-- ---------- categories / channels / channel_fields: vertical managers ----------
DROP POLICY IF EXISTS "categories_admin_write" ON categories;
DROP POLICY IF EXISTS "categories_manage"      ON categories;
CREATE POLICY "categories_manage" ON categories FOR ALL TO authenticated
  USING (can_manage_vertical(vertical_id)) WITH CHECK (can_manage_vertical(vertical_id));

DROP POLICY IF EXISTS "channels_admin_write" ON channels;
DROP POLICY IF EXISTS "channels_manage"      ON channels;
CREATE POLICY "channels_manage" ON channels FOR ALL TO authenticated
  USING (can_manage_vertical(vertical_id))
  WITH CHECK (can_manage_vertical(category_vertical(category_id)));

DROP POLICY IF EXISTS "channel_fields_admin_write" ON channel_fields;
DROP POLICY IF EXISTS "channel_fields_manage"      ON channel_fields;
CREATE POLICY "channel_fields_manage" ON channel_fields FOR ALL TO authenticated
  USING (can_manage_vertical(channel_vertical(channel_id)))
  WITH CHECK (can_manage_vertical(channel_vertical(channel_id)));

-- ---------- channel owners / targets / resources / learnings ----------
DROP POLICY IF EXISTS "channel_owners_admin_write" ON channel_owners;
DROP POLICY IF EXISTS "channel_owners_manage"      ON channel_owners;
CREATE POLICY "channel_owners_manage" ON channel_owners FOR ALL TO authenticated
  USING (can_manage_vertical(channel_vertical(channel_id)))
  WITH CHECK (can_manage_vertical(channel_vertical(channel_id)));

DROP POLICY IF EXISTS "channel_targets_insert" ON channel_targets;
DROP POLICY IF EXISTS "channel_targets_delete" ON channel_targets;
CREATE POLICY "channel_targets_insert" ON channel_targets FOR INSERT TO authenticated
  WITH CHECK (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)));
CREATE POLICY "channel_targets_delete" ON channel_targets FOR DELETE TO authenticated
  USING (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)));

DROP POLICY IF EXISTS "channel_resources_update" ON channel_resources;
DROP POLICY IF EXISTS "channel_resources_delete" ON channel_resources;
CREATE POLICY "channel_resources_update" ON channel_resources FOR UPDATE TO authenticated
  USING (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)))
  WITH CHECK (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)));
CREATE POLICY "channel_resources_delete" ON channel_resources FOR DELETE TO authenticated
  USING (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)));

DROP POLICY IF EXISTS "channel_learnings_delete" ON channel_learnings;
CREATE POLICY "channel_learnings_delete" ON channel_learnings FOR DELETE TO authenticated
  USING (added_by = auth.uid() OR can_manage_vertical(channel_vertical(channel_id)));

-- ---------- budget_periods: global = admin, scoped = vertical managers ----------
DROP POLICY IF EXISTS "budget_periods_admin_write" ON budget_periods;
DROP POLICY IF EXISTS "budget_periods_manage"      ON budget_periods;
CREATE POLICY "budget_periods_manage" ON budget_periods FOR ALL TO authenticated
  USING (CASE WHEN vertical_id IS NULL THEN is_admin() ELSE can_manage_vertical(vertical_id) END)
  WITH CHECK (
    CASE
      WHEN scope_type::text = 'global'   THEN is_admin()
      WHEN scope_type::text = 'vertical' THEN can_manage_vertical(scope_id)
      WHEN scope_type::text = 'category' THEN can_manage_vertical(category_vertical(scope_id))
      WHEN scope_type::text = 'channel'  THEN can_manage_vertical(channel_vertical(scope_id))
      ELSE is_admin()
    END
  );

-- ---------- vertical_resources ----------
ALTER TABLE vertical_resources ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "vertical_resources_read"  ON vertical_resources;
DROP POLICY IF EXISTS "vertical_resources_write" ON vertical_resources;
CREATE POLICY "vertical_resources_read"  ON vertical_resources FOR SELECT TO authenticated USING (true);
CREATE POLICY "vertical_resources_write" ON vertical_resources FOR ALL TO authenticated
  USING (can_manage_vertical(vertical_id)) WITH CHECK (can_manage_vertical(vertical_id));

-- ---------- slack_settings: vertical managers too ----------
DROP POLICY IF EXISTS "slack_settings_admin"  ON slack_settings;
DROP POLICY IF EXISTS "slack_settings_manage" ON slack_settings;
CREATE POLICY "slack_settings_manage" ON slack_settings FOR ALL TO authenticated
  USING (is_admin() OR can_manage_vertical(vertical_id))
  WITH CHECK (is_admin() OR can_manage_vertical(vertical_id));

-- ############################################################
-- 016_taxonomy_templates.sql
-- ############################################################
-- ============================================================
-- Migration 016: Taxonomy templates + vertical RPCs
-- A template is a JSON snapshot of a vertical's taxonomy (categories ->
-- channels -> sub-channels, with function links and custom fields, but NO
-- ids, owners, activities or budgets). New verticals can be cloned from one.
-- RPCs run SECURITY DEFINER so the clone is atomic and does not depend on
-- per-row RLS checks; each guards with can_manage_vertical / is_admin.
-- Idempotent.
-- ============================================================

CREATE TABLE IF NOT EXISTS taxonomy_templates (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  name TEXT NOT NULL,
  slug TEXT NOT NULL UNIQUE,
  description TEXT,
  body JSONB NOT NULL,
  source_vertical_id UUID REFERENCES verticals(id) ON DELETE SET NULL,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);

DROP TRIGGER IF EXISTS taxonomy_templates_updated_at ON taxonomy_templates;
CREATE TRIGGER taxonomy_templates_updated_at BEFORE UPDATE ON taxonomy_templates
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

ALTER TABLE taxonomy_templates ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "taxonomy_templates_read"   ON taxonomy_templates;
DROP POLICY IF EXISTS "taxonomy_templates_insert" ON taxonomy_templates;
DROP POLICY IF EXISTS "taxonomy_templates_update" ON taxonomy_templates;
DROP POLICY IF EXISTS "taxonomy_templates_delete" ON taxonomy_templates;
CREATE POLICY "taxonomy_templates_read"   ON taxonomy_templates FOR SELECT TO authenticated USING (true);
CREATE POLICY "taxonomy_templates_insert" ON taxonomy_templates FOR INSERT TO authenticated
  WITH CHECK (is_admin() OR (source_vertical_id IS NOT NULL AND can_manage_vertical(source_vertical_id)));
CREATE POLICY "taxonomy_templates_update" ON taxonomy_templates FOR UPDATE TO authenticated
  USING (created_by = auth.uid() OR is_admin()) WITH CHECK (created_by = auth.uid() OR is_admin());
CREATE POLICY "taxonomy_templates_delete" ON taxonomy_templates FOR DELETE TO authenticated
  USING (created_by = auth.uid() OR is_admin());

GRANT ALL ON taxonomy_templates TO authenticated, service_role;

-- ---------- slugify helper ----------
CREATE OR REPLACE FUNCTION public.slugify(txt TEXT)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
  SELECT trim(both '-' from regexp_replace(lower(replace(coalesce(txt, ''), '&', 'and')), '[^a-z0-9]+', '-', 'g'));
$$;

-- ---------- snapshot: one channel node (recursive) ----------
CREATE OR REPLACE FUNCTION public.snapshot_channel_node(p_channel_id UUID)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE
  ch channels%ROWTYPE;
  fields JSONB;
  children JSONB;
  fn_slug TEXT;
BEGIN
  SELECT * INTO ch FROM channels WHERE id = p_channel_id;
  SELECT slug INTO fn_slug FROM functions WHERE id = ch.function_id;

  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'name', f.name, 'slug', f.slug, 'field_type', f.field_type::text,
           'surface', f.surface::text, 'is_required', f.is_required, 'options', f.options,
           'formula', f.formula, 'is_auto_calc', f.is_auto_calc, 'description', f.description,
           'sort_order', f.sort_order, 'cascades_to_children', f.cascades_to_children
         ) ORDER BY f.sort_order), '[]'::jsonb)
    INTO fields
    FROM channel_fields f WHERE f.channel_id = ch.id;

  SELECT COALESCE(jsonb_agg(snapshot_channel_node(c.id) ORDER BY c.sort_order, c.name), '[]'::jsonb)
    INTO children
    FROM channels c WHERE c.parent_channel_id = ch.id;

  RETURN jsonb_build_object(
    'name', ch.name, 'slug', ch.slug, 'sort_order', ch.sort_order,
    'tier', ch.tier, 'goal', ch.goal, 'target', ch.target, 'budget_note', ch.budget_note,
    'function_slug', fn_slug,
    'extra', (ch.extra - 'bp_id' - 'owner_note'),
    'fields', fields,
    'children', children
  );
END $$;

-- ---------- snapshot: whole vertical ----------
CREATE OR REPLACE FUNCTION public.snapshot_vertical_taxonomy(p_vertical_id UUID)
RETURNS JSONB LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path = public AS $$
DECLARE cats JSONB;
BEGIN
  SELECT COALESCE(jsonb_agg(jsonb_build_object(
           'name', c.name, 'slug', c.slug, 'icon', c.icon, 'sort_order', c.sort_order,
           'channels', (
             SELECT COALESCE(jsonb_agg(snapshot_channel_node(ch.id) ORDER BY ch.sort_order, ch.name), '[]'::jsonb)
               FROM channels ch WHERE ch.category_id = c.id AND ch.parent_channel_id IS NULL
           )
         ) ORDER BY c.sort_order, c.name), '[]'::jsonb)
    INTO cats
    FROM categories c WHERE c.vertical_id = p_vertical_id AND c.is_active;
  RETURN jsonb_build_object('version', 1, 'categories', cats);
END $$;

-- ---------- apply: one channel node (recursive) ----------
CREATE OR REPLACE FUNCTION public.apply_template_channel(
  p_vertical_id UUID, p_category_id UUID, p_parent_id UUID, node JSONB, p_depth INT
) RETURNS INT LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  new_id UUID;
  fn_id UUID;
  fld JSONB;
  child JSONB;
  n INT := 1;
  v_slug TEXT;
BEGIN
  IF p_depth > 3 THEN RETURN 0; END IF;
  v_slug := COALESCE(NULLIF(node->>'slug', ''), slugify(node->>'name'));
  SELECT id INTO fn_id FROM functions WHERE slug = node->>'function_slug';

  SELECT id INTO new_id FROM channels
   WHERE category_id = p_category_id
     AND COALESCE(parent_channel_id, '00000000-0000-0000-0000-000000000000'::uuid)
         = COALESCE(p_parent_id, '00000000-0000-0000-0000-000000000000'::uuid)
     AND slug = v_slug;

  IF new_id IS NULL THEN
    INSERT INTO channels (category_id, parent_channel_id, name, slug, sort_order, tier, goal, target, budget_note, extra, function_id, vertical_id)
    VALUES (
      p_category_id, p_parent_id, node->>'name', v_slug,
      COALESCE((node->>'sort_order')::int, 0),
      NULLIF(node->>'tier', ''), NULLIF(node->>'goal', ''), NULLIF(node->>'target', ''), NULLIF(node->>'budget_note', ''),
      COALESCE(node->'extra', '{}'::jsonb), fn_id, p_vertical_id
    ) RETURNING id INTO new_id;
  ELSE
    n := 0; -- already there (idempotent re-apply): update nothing, still recurse
  END IF;

  FOR fld IN SELECT * FROM jsonb_array_elements(COALESCE(node->'fields', '[]'::jsonb)) LOOP
    INSERT INTO channel_fields (channel_id, name, slug, field_type, surface, is_required, options, formula, is_auto_calc, description, sort_order, cascades_to_children)
    VALUES (
      new_id, fld->>'name', fld->>'slug',
      (fld->>'field_type')::field_type, (fld->>'surface')::field_surface,
      COALESCE((fld->>'is_required')::boolean, false),
      CASE WHEN fld ? 'options' AND jsonb_typeof(fld->'options') <> 'null' THEN fld->'options' ELSE NULL END,
      NULLIF(fld->>'formula', ''),
      COALESCE((fld->>'is_auto_calc')::boolean, false),
      NULLIF(fld->>'description', ''),
      COALESCE((fld->>'sort_order')::int, 0),
      COALESCE((fld->>'cascades_to_children')::boolean, false)
    )
    ON CONFLICT (channel_id, slug) DO NOTHING;
  END LOOP;

  FOR child IN SELECT * FROM jsonb_array_elements(COALESCE(node->'children', '[]'::jsonb)) LOOP
    n := n + apply_template_channel(p_vertical_id, p_category_id, new_id, child, p_depth + 1);
  END LOOP;
  RETURN n;
END $$;

-- ---------- apply: whole template onto a vertical ----------
CREATE OR REPLACE FUNCTION public.apply_taxonomy_template(p_vertical_id UUID, p_template_id UUID)
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  body JSONB;
  cat JSONB;
  ch JSONB;
  cat_id UUID;
  cat_slug TEXT;
  n_cats INT := 0;
  n_channels INT := 0;
BEGIN
  IF NOT can_manage_vertical(p_vertical_id) THEN
    RAISE EXCEPTION 'forbidden: not a manager of vertical %', p_vertical_id;
  END IF;
  SELECT t.body INTO body FROM taxonomy_templates t WHERE t.id = p_template_id;
  IF body IS NULL THEN RAISE EXCEPTION 'template % not found', p_template_id; END IF;

  FOR cat IN SELECT * FROM jsonb_array_elements(COALESCE(body->'categories', '[]'::jsonb)) LOOP
    cat_slug := COALESCE(NULLIF(cat->>'slug', ''), slugify(cat->>'name'));
    INSERT INTO categories (vertical_id, name, slug, icon, sort_order, is_active)
    VALUES (p_vertical_id, cat->>'name', cat_slug, NULLIF(cat->>'icon', ''), COALESCE((cat->>'sort_order')::int, 0), true)
    ON CONFLICT (vertical_id, slug) DO UPDATE SET name = EXCLUDED.name
    RETURNING id INTO cat_id;
    n_cats := n_cats + 1;
    FOR ch IN SELECT * FROM jsonb_array_elements(COALESCE(cat->'channels', '[]'::jsonb)) LOOP
      n_channels := n_channels + apply_template_channel(p_vertical_id, cat_id, NULL, ch, 1);
    END LOOP;
  END LOOP;

  RETURN jsonb_build_object('categories', n_cats, 'channels', n_channels);
END $$;

-- ---------- save a vertical as a template ----------
CREATE OR REPLACE FUNCTION public.save_vertical_as_template(
  p_vertical_id UUID, p_name TEXT, p_slug TEXT DEFAULT NULL, p_description TEXT DEFAULT NULL
) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  t_id UUID;
  t_slug TEXT;
BEGIN
  IF NOT can_manage_vertical(p_vertical_id) THEN
    RAISE EXCEPTION 'forbidden: not a manager of vertical %', p_vertical_id;
  END IF;
  t_slug := COALESCE(NULLIF(p_slug, ''), slugify(p_name));
  INSERT INTO taxonomy_templates (name, slug, description, body, source_vertical_id, created_by)
  VALUES (p_name, t_slug, p_description, snapshot_vertical_taxonomy(p_vertical_id), p_vertical_id, auth.uid())
  ON CONFLICT (slug) DO UPDATE
    SET name = EXCLUDED.name, description = EXCLUDED.description,
        body = EXCLUDED.body, source_vertical_id = EXCLUDED.source_vertical_id
  RETURNING id INTO t_id;
  RETURN t_id;
END $$;

-- ---------- create a vertical (admin), optionally from a template ----------
CREATE OR REPLACE FUNCTION public.create_vertical(
  p_name TEXT,
  p_slug TEXT DEFAULT NULL,
  p_settings JSONB DEFAULT NULL,
  p_template_id UUID DEFAULT NULL,
  p_owner_emails TEXT[] DEFAULT '{}',
  p_description TEXT DEFAULT NULL
) RETURNS UUID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  v_id UUID;
  v_slug TEXT;
  em TEXT;
  i INT := 0;
BEGIN
  IF NOT (is_admin() OR is_service_role()) THEN
    RAISE EXCEPTION 'forbidden: only admins create verticals';
  END IF;
  v_slug := COALESCE(NULLIF(p_slug, ''), slugify(p_name));
  INSERT INTO verticals (name, slug, description, settings, created_by, sort_order)
  VALUES (
    p_name, v_slug, p_description,
    COALESCE(p_settings, '{"leads_pipeline":false,"weekly_report_builder":false,"resources":false,"hubspot_contacts":false}'::jsonb),
    auth.uid(),
    (SELECT COALESCE(MAX(sort_order), 0) + 1 FROM verticals)
  ) RETURNING id INTO v_id;

  FOREACH em IN ARRAY COALESCE(p_owner_emails, '{}') LOOP
    IF em IS NOT NULL AND em <> '' THEN
      INSERT INTO vertical_owners (vertical_id, email, user_id, sort_order)
      VALUES (v_id, lower(em), (SELECT id FROM users WHERE lower(email) = lower(em) LIMIT 1), i)
      ON CONFLICT (vertical_id, email) DO NOTHING;
      i := i + 1;
    END IF;
  END LOOP;

  IF p_template_id IS NOT NULL THEN
    PERFORM apply_taxonomy_template(v_id, p_template_id);
  END IF;
  RETURN v_id;
END $$;

GRANT EXECUTE ON FUNCTION public.slugify(TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.snapshot_channel_node(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.snapshot_vertical_taxonomy(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.apply_template_channel(UUID, UUID, UUID, JSONB, INT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.apply_taxonomy_template(UUID, UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.save_vertical_as_template(UUID, TEXT, TEXT, TEXT) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.create_vertical(TEXT, TEXT, JSONB, UUID, TEXT[], TEXT) TO authenticated, service_role;

-- ############################################################
-- 017_campaigns.sql
-- ############################################################
-- ============================================================
-- Migration 017: Hero campaigns (launches, thunderclaps, big campaigns)
-- A campaign is the "hero action item" of the week/month: it shows as a
-- banner on every dashboard, has its own tracker page, links tasks from any
-- channel, and (for thunderclaps) tracks who in the team has done their bit.
-- vertical_id NULL = company-wide. Idempotent; safe to paste on the live DB.
-- ============================================================

CREATE TABLE IF NOT EXISTS campaigns (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  vertical_id UUID REFERENCES verticals(id) ON DELETE CASCADE,   -- NULL = workspace-wide
  kind TEXT NOT NULL DEFAULT 'campaign' CHECK (kind IN ('launch', 'thunderclap', 'campaign')),
  name TEXT NOT NULL,
  slug TEXT NOT NULL,
  headline TEXT,                 -- one-line banner copy
  description TEXT,
  cta_label TEXT,
  cta_url TEXT,
  starts_on DATE,
  ends_on DATE,
  status TEXT NOT NULL DEFAULT 'upcoming' CHECK (status IN ('upcoming', 'live', 'done', 'cancelled')),
  is_pinned BOOLEAN NOT NULL DEFAULT TRUE,   -- show in banners while active
  color TEXT,                                -- accent (e.g. 'violet', 'amber')
  -- thunderclap: what every participant must do (post, share, comment...)
  ask TEXT,
  created_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  UNIQUE (vertical_id, slug)
);
CREATE UNIQUE INDEX IF NOT EXISTS campaigns_workspace_slug_uq ON campaigns(slug) WHERE vertical_id IS NULL;
CREATE INDEX IF NOT EXISTS campaigns_vertical_idx ON campaigns(vertical_id);
CREATE INDEX IF NOT EXISTS campaigns_status_idx ON campaigns(status, is_pinned);

DROP TRIGGER IF EXISTS campaigns_updated_at ON campaigns;
CREATE TRIGGER campaigns_updated_at BEFORE UPDATE ON campaigns
  FOR EACH ROW EXECUTE FUNCTION update_updated_at();

-- Owners of the campaign (the "champions"); by email, resolved on sign-in.
CREATE TABLE IF NOT EXISTS campaign_owners (
  campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  sort_order INT NOT NULL DEFAULT 0,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (campaign_id, email)
);
CREATE INDEX IF NOT EXISTS campaign_owners_user_idx ON campaign_owners(user_id);

-- Thunderclap participants: everyone who has to do the ask, and whether they did.
CREATE TABLE IF NOT EXISTS campaign_participants (
  campaign_id UUID NOT NULL REFERENCES campaigns(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  done_at TIMESTAMPTZ,
  proof_url TEXT,
  note TEXT,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (campaign_id, email)
);
CREATE INDEX IF NOT EXISTS campaign_participants_user_idx ON campaign_participants(user_id);

-- Tasks can belong to a campaign (any channel, any vertical).
ALTER TABLE tasks ADD COLUMN IF NOT EXISTS campaign_id UUID REFERENCES campaigns(id) ON DELETE SET NULL;
CREATE INDEX IF NOT EXISTS tasks_campaign_idx ON tasks(campaign_id);

-- handle_new_user: also link campaign owners / participants by email.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    CASE WHEN NEW.email = 'kailash.gm@lyzr.ai' THEN 'admin'::user_role ELSE 'member'::user_role END
  );

  UPDATE pending_mentions
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id
    FROM pending_mentions pm
   WHERE pm.email = NEW.email AND pm.resolved_user_id = NEW.id;

  UPDATE pending_invites
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE
           WHEN pa.role = 'primary' AND EXISTS (
             SELECT 1 FROM task_assignments ta
              WHERE ta.task_id = pa.task_id AND ta.role = 'primary'
           ) THEN 'secondary'::assignment_role
           ELSE pa.role
         END,
         pa.assigned_by
    FROM pending_assignments pa
   WHERE pa.email = NEW.email AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;

  UPDATE pending_assignments
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  UPDATE channel_owners  SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE vertical_owners SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE function_owners SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  -- NEW (017)
  UPDATE campaign_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;

  RETURN NEW;
END;
$$;

-- ---------- RLS ----------
-- Read: everyone. Create/edit: admin, the vertical's managers (or admin only
-- for workspace-wide), or a campaign owner. Participants can tick themselves.
CREATE OR REPLACE FUNCTION public.is_campaign_owner(c UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM campaign_owners WHERE campaign_id = c AND user_id = auth.uid());
$$;
CREATE OR REPLACE FUNCTION public.can_manage_campaign(c UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT is_admin() OR is_service_role() OR is_campaign_owner(c)
      OR EXISTS (SELECT 1 FROM campaigns x WHERE x.id = c AND x.vertical_id IS NOT NULL AND is_vertical_owner(x.vertical_id));
$$;
GRANT EXECUTE ON FUNCTION public.is_campaign_owner(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_manage_campaign(UUID) TO authenticated, service_role;

ALTER TABLE campaigns ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "campaigns_read"   ON campaigns;
DROP POLICY IF EXISTS "campaigns_insert" ON campaigns;
DROP POLICY IF EXISTS "campaigns_update" ON campaigns;
DROP POLICY IF EXISTS "campaigns_delete" ON campaigns;
CREATE POLICY "campaigns_read"   ON campaigns FOR SELECT TO authenticated USING (true);
CREATE POLICY "campaigns_insert" ON campaigns FOR INSERT TO authenticated
  WITH CHECK (CASE WHEN vertical_id IS NULL THEN is_admin() ELSE can_manage_vertical(vertical_id) END);
CREATE POLICY "campaigns_update" ON campaigns FOR UPDATE TO authenticated
  USING (can_manage_campaign(id)) WITH CHECK (can_manage_campaign(id));
CREATE POLICY "campaigns_delete" ON campaigns FOR DELETE TO authenticated
  USING (is_admin() OR (vertical_id IS NOT NULL AND is_vertical_owner(vertical_id)));

ALTER TABLE campaign_owners ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "campaign_owners_read"  ON campaign_owners;
DROP POLICY IF EXISTS "campaign_owners_write" ON campaign_owners;
CREATE POLICY "campaign_owners_read"  ON campaign_owners FOR SELECT TO authenticated USING (true);
CREATE POLICY "campaign_owners_write" ON campaign_owners FOR ALL TO authenticated
  USING (can_manage_campaign(campaign_id)) WITH CHECK (can_manage_campaign(campaign_id));

ALTER TABLE campaign_participants ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "campaign_participants_read"   ON campaign_participants;
DROP POLICY IF EXISTS "campaign_participants_manage" ON campaign_participants;
DROP POLICY IF EXISTS "campaign_participants_self"   ON campaign_participants;
CREATE POLICY "campaign_participants_read"   ON campaign_participants FOR SELECT TO authenticated USING (true);
CREATE POLICY "campaign_participants_manage" ON campaign_participants FOR ALL TO authenticated
  USING (can_manage_campaign(campaign_id)) WITH CHECK (can_manage_campaign(campaign_id));
-- A participant may mark their own row done (and add proof), nothing else.
CREATE POLICY "campaign_participants_self"   ON campaign_participants FOR UPDATE TO authenticated
  USING (user_id = auth.uid()) WITH CHECK (user_id = auth.uid());

GRANT ALL ON campaigns, campaign_owners, campaign_participants TO authenticated, service_role;

