-- Promote anyone already signed in.
UPDATE users SET role = 'admin'::user_role
 WHERE lower(email) IN (SELECT lower(email) FROM admin_emails) AND role <> 'admin';

-- handle_new_user: role comes from admin_emails instead of one hard-coded address.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (
    NEW.id,
    NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    CASE WHEN EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) = lower(NEW.email))
         THEN 'admin'::user_role ELSE 'member'::user_role END
  );

  UPDATE pending_mentions
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id
    FROM pending_mentions pm
   WHERE pm.email = NEW.email AND pm.resolved_user_id = NEW.id;

  UPDATE pending_invites
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE
           WHEN pa.role = 'primary' AND EXISTS (
             SELECT 1 FROM task_assignments ta
              WHERE ta.task_id = pa.task_id AND ta.role = 'primary'
           ) THEN 'secondary'::assignment_role
           ELSE pa.role
         END,
         pa.assigned_by
    FROM pending_assignments pa
   WHERE pa.email = NEW.email AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;

  UPDATE pending_assignments
     SET resolved_user_id = NEW.id, resolved_at = now()
   WHERE email = NEW.email AND resolved_user_id IS NULL;

  UPDATE channel_owners        SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE vertical_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE function_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE campaign_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;

  RETURN NEW;
END;
$$;

-- ############################################################
-- 019_members_roles_history.sql
-- ############################################################
-- ============================================================
-- Migration 019: members, leadership badge, owner-scoped rights,
-- task edit history, suggested edits, cross-channel sub-tasks.
-- Per Kailash 2026-09-25:
--   * anyone who is a member of a vertical can create tasks / sub-tasks there
--   * vertical owners create channels; a channel owner may add sub-channels
--     under their own channel and set owners below them
--   * task owners (and admins / vertical owners / channel owners) edit and
--     delete; everyone else suggests an edit the owner accepts or rejects
--   * every field change on a task is recorded (DB trigger, not client)
--   * Leadership = read-across badge, no edit rights by itself
-- Idempotent; safe to paste on the live DB.
-- ============================================================

-- ---------- badges ----------
CREATE TABLE IF NOT EXISTS leadership_emails (
  email TEXT PRIMARY KEY,
  added_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
ALTER TABLE leadership_emails ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "leadership_emails_read"  ON leadership_emails;
DROP POLICY IF EXISTS "leadership_emails_write" ON leadership_emails;
CREATE POLICY "leadership_emails_read"  ON leadership_emails FOR SELECT TO authenticated USING (true);
CREATE POLICY "leadership_emails_write" ON leadership_emails FOR ALL TO authenticated USING (is_admin()) WITH CHECK (is_admin());
GRANT ALL ON leadership_emails TO authenticated, service_role;
-- Admins are leadership by default.
INSERT INTO leadership_emails (email) SELECT email FROM admin_emails ON CONFLICT DO NOTHING;

-- ---------- vertical members ----------
CREATE TABLE IF NOT EXISTS vertical_members (
  vertical_id UUID NOT NULL REFERENCES verticals(id) ON DELETE CASCADE,
  email TEXT NOT NULL,
  user_id UUID REFERENCES users(id) ON DELETE SET NULL,
  added_by UUID REFERENCES users(id) ON DELETE SET NULL,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY (vertical_id, email)
);
CREATE INDEX IF NOT EXISTS vertical_members_user_idx ON vertical_members(user_id);
UPDATE vertical_members m SET user_id = u.id FROM users u WHERE m.user_id IS NULL AND lower(u.email) = lower(m.email);

-- Everyone who owns something in a vertical is a member of it, plus explicit rows.
CREATE OR REPLACE FUNCTION public.is_vertical_member(v UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT v IS NOT NULL AND (
    is_admin() OR is_service_role() OR is_vertical_owner(v)
    OR EXISTS (SELECT 1 FROM vertical_members WHERE vertical_id = v AND user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM channel_owners o JOIN channels c ON c.id = o.channel_id WHERE c.vertical_id = v AND o.user_id = auth.uid())
    OR EXISTS (SELECT 1 FROM function_owners f JOIN channels c ON c.function_id = f.function_id WHERE c.vertical_id = v AND f.user_id = auth.uid())
  );
$$;
GRANT EXECUTE ON FUNCTION public.is_vertical_member(UUID) TO authenticated, service_role;

ALTER TABLE vertical_members ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "vertical_members_read"   ON vertical_members;
DROP POLICY IF EXISTS "vertical_members_manage" ON vertical_members;
CREATE POLICY "vertical_members_read"   ON vertical_members FOR SELECT TO authenticated USING (true);
CREATE POLICY "vertical_members_manage" ON vertical_members FOR ALL TO authenticated
  USING (can_manage_vertical(vertical_id)) WITH CHECK (can_manage_vertical(vertical_id));
GRANT ALL ON vertical_members TO authenticated, service_role;

-- ---------- channel-owner scoped rights ----------
-- True when the caller owns channel c, its parent, or its grandparent.
CREATE OR REPLACE FUNCTION public.owns_channel_or_ancestor(c UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  WITH RECURSIVE up AS (
    SELECT id, parent_channel_id, 0 AS depth FROM channels WHERE id = c
    UNION ALL
    SELECT ch.id, ch.parent_channel_id, up.depth + 1 FROM channels ch JOIN up ON ch.id = up.parent_channel_id WHERE up.depth < 4
  )
  SELECT EXISTS (SELECT 1 FROM channel_owners o JOIN up ON up.id = o.channel_id WHERE o.user_id = auth.uid());
$$;
GRANT EXECUTE ON FUNCTION public.owns_channel_or_ancestor(UUID) TO authenticated, service_role;

DROP POLICY IF EXISTS "channels_manage" ON channels;
DROP POLICY IF EXISTS "channels_insert" ON channels;
DROP POLICY IF EXISTS "channels_update" ON channels;
DROP POLICY IF EXISTS "channels_delete" ON channels;
CREATE POLICY "channels_insert" ON channels FOR INSERT TO authenticated
  WITH CHECK (can_manage_vertical(category_vertical(category_id))
           OR (parent_channel_id IS NOT NULL AND owns_channel_or_ancestor(parent_channel_id)));
CREATE POLICY "channels_update" ON channels FOR UPDATE TO authenticated
  USING (can_manage_vertical(vertical_id) OR owns_channel_or_ancestor(id))
  WITH CHECK (can_manage_vertical(vertical_id) OR owns_channel_or_ancestor(id));
CREATE POLICY "channels_delete" ON channels FOR DELETE TO authenticated
  USING (can_manage_vertical(vertical_id));

DROP POLICY IF EXISTS "channel_owners_manage" ON channel_owners;
CREATE POLICY "channel_owners_manage" ON channel_owners FOR ALL TO authenticated
  USING (can_manage_vertical(channel_vertical(channel_id)) OR owns_channel_or_ancestor(channel_id))
  WITH CHECK (can_manage_vertical(channel_vertical(channel_id)) OR owns_channel_or_ancestor(channel_id));

-- ---------- tasks: members create, owners edit/delete ----------
CREATE OR REPLACE FUNCTION public.is_task_owner(t UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM task_assignments WHERE task_id = t AND user_id = auth.uid())
      OR EXISTS (SELECT 1 FROM tasks WHERE id = t AND created_by = auth.uid());
$$;
CREATE OR REPLACE FUNCTION public.can_edit_task(t UUID)
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT is_admin() OR is_service_role() OR is_task_owner(t)
      OR EXISTS (SELECT 1 FROM tasks x WHERE x.id = t AND (is_vertical_owner(channel_vertical(x.channel_id)) OR owns_channel_or_ancestor(x.channel_id)))
      -- owners of the parent activity may edit its sub-tasks
      OR EXISTS (SELECT 1 FROM tasks x WHERE x.id = t AND x.parent_task_id IS NOT NULL AND is_task_owner(x.parent_task_id));
$$;
GRANT EXECUTE ON FUNCTION public.is_task_owner(UUID) TO authenticated, service_role;
GRANT EXECUTE ON FUNCTION public.can_edit_task(UUID) TO authenticated, service_role;

DROP POLICY IF EXISTS "tasks_insert" ON tasks;
DROP POLICY IF EXISTS "tasks_update" ON tasks;
DROP POLICY IF EXISTS "tasks_delete" ON tasks;
CREATE POLICY "tasks_insert" ON tasks FOR INSERT TO authenticated
  WITH CHECK (auth.uid() = created_by AND is_vertical_member(channel_vertical(channel_id)));
CREATE POLICY "tasks_update" ON tasks FOR UPDATE TO authenticated
  USING (can_edit_task(id)) WITH CHECK (can_edit_task(id));
CREATE POLICY "tasks_delete" ON tasks FOR DELETE TO authenticated
  USING (can_edit_task(id));

-- Assignments: whoever may edit the task may change its owners; creating a
-- task inserts its own assignments (creator is owner via created_by).
DROP POLICY IF EXISTS "task_assignments_write" ON task_assignments;
CREATE POLICY "task_assignments_write" ON task_assignments FOR ALL TO authenticated
  USING (can_edit_task(task_id)) WITH CHECK (can_edit_task(task_id));

-- ---------- task history (trigger-written) ----------
CREATE OR REPLACE FUNCTION public.log_task_edit()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  f TEXT;
  fields TEXT[] := ARRAY['title','description','priority','status','due_date','channel_id','parent_task_id',
                         'budget_allocated','budget_period_id','campaign_id','result_url','blocked_reason','blocked_by_email',
                         'planning_fields','tracker_fields'];
  o JSONB := to_jsonb(OLD);
  n JSONB := to_jsonb(NEW);
BEGIN
  FOREACH f IN ARRAY fields LOOP
    IF (o -> f) IS DISTINCT FROM (n -> f) THEN
      -- status changes are already logged by the client as 'status_changed'
      IF f = 'status' THEN CONTINUE; END IF;
      INSERT INTO activity_log (task_id, actor_id, action, from_value, to_value)
      VALUES (NEW.id, auth.uid(), 'edited', jsonb_build_object('field', f, 'value', o -> f), jsonb_build_object('field', f, 'value', n -> f));
    END IF;
  END LOOP;
  RETURN NEW;
END;
$$;
DROP TRIGGER IF EXISTS tasks_log_edit ON tasks;
CREATE TRIGGER tasks_log_edit AFTER UPDATE ON tasks FOR EACH ROW EXECUTE FUNCTION log_task_edit();

-- ---------- suggested edits ----------
CREATE TABLE IF NOT EXISTS task_suggestions (
  id UUID PRIMARY KEY DEFAULT gen_random_uuid(),
  task_id UUID NOT NULL REFERENCES tasks(id) ON DELETE CASCADE,
  suggested_by UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  patch JSONB NOT NULL,            -- { field: value, ... } same keys updateTask accepts
  note TEXT,
  status TEXT NOT NULL DEFAULT 'pending' CHECK (status IN ('pending', 'accepted', 'rejected')),
  resolved_by UUID REFERENCES users(id) ON DELETE SET NULL,
  resolved_at TIMESTAMPTZ,
  created_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE INDEX IF NOT EXISTS task_suggestions_task_idx ON task_suggestions(task_id, status);
ALTER TABLE task_suggestions ENABLE ROW LEVEL SECURITY;
DROP POLICY IF EXISTS "task_suggestions_read"    ON task_suggestions;
DROP POLICY IF EXISTS "task_suggestions_insert"  ON task_suggestions;
DROP POLICY IF EXISTS "task_suggestions_resolve" ON task_suggestions;
DROP POLICY IF EXISTS "task_suggestions_delete"  ON task_suggestions;
CREATE POLICY "task_suggestions_read"    ON task_suggestions FOR SELECT TO authenticated USING (true);
CREATE POLICY "task_suggestions_insert"  ON task_suggestions FOR INSERT TO authenticated WITH CHECK (suggested_by = auth.uid());
CREATE POLICY "task_suggestions_resolve" ON task_suggestions FOR UPDATE TO authenticated
  USING (can_edit_task(task_id)) WITH CHECK (can_edit_task(task_id));
CREATE POLICY "task_suggestions_delete"  ON task_suggestions FOR DELETE TO authenticated
  USING (suggested_by = auth.uid() OR can_edit_task(task_id));
GRANT ALL ON task_suggestions TO authenticated, service_role;

-- ---------- handle_new_user: link vertical_members ----------
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (
    NEW.id, NEW.email,
    COALESCE(NEW.raw_user_meta_data->>'full_name', split_part(NEW.email, '@', 1)),
    NEW.raw_user_meta_data->>'avatar_url',
    CASE WHEN EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) = lower(NEW.email))
         THEN 'admin'::user_role ELSE 'member'::user_role END
  );
  UPDATE pending_mentions SET resolved_user_id = NEW.id, resolved_at = now() WHERE email = NEW.email AND resolved_user_id IS NULL;
  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id FROM pending_mentions pm
   WHERE pm.email = NEW.email AND pm.resolved_user_id = NEW.id;
  UPDATE pending_invites SET resolved_user_id = NEW.id, resolved_at = now() WHERE email = NEW.email AND resolved_user_id IS NULL;
  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE WHEN pa.role = 'primary' AND EXISTS (SELECT 1 FROM task_assignments ta WHERE ta.task_id = pa.task_id AND ta.role = 'primary')
              THEN 'secondary'::assignment_role ELSE pa.role END,
         pa.assigned_by
    FROM pending_assignments pa WHERE pa.email = NEW.email AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;
  UPDATE pending_assignments SET resolved_user_id = NEW.id, resolved_at = now() WHERE email = NEW.email AND resolved_user_id IS NULL;
  UPDATE channel_owners        SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE vertical_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE vertical_members      SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE function_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE campaign_owners       SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) = lower(NEW.email) AND user_id IS NULL;
  RETURN NEW;
END;
$$;

-- Everyone who already signed in is a member of every vertical, so nobody
-- is locked out of creating tasks on cutover day. Trim from Members later.
INSERT INTO vertical_members (vertical_id, email, user_id)
SELECT v.id, u.email, u.id FROM verticals v CROSS JOIN users u
WHERE u.email <> 'preview@lyzr.ai'
ON CONFLICT DO NOTHING;

-- ############################################################
-- 020_task_notifications.sql
-- ############################################################
-- ============================================================
-- Migration 020: notifications for everything that happens on a task.
-- Written by database triggers so no client path can skip them.
-- "Related people" of a task = its owners, its creator, the owners of its
-- parent task, the owners of its channel (effective, incl. domain owners),
-- and anyone who suggested an edit on it. The actor never notifies themself.
-- Idempotent; safe to paste on the live DB. Run AFTER 019.
-- ============================================================

-- New kinds. (ADD VALUE cannot be used by other statements in the same
-- transaction; the trigger bodies below are only compiled at run time.)
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'task_edited';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'checklist';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'subtask_added';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'suggestion';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'suggestion_resolved';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'campaign_ask';
ALTER TYPE notification_type ADD VALUE IF NOT EXISTS 'task_created';

-- Everyone who should hear about task t.
CREATE OR REPLACE FUNCTION public.task_watchers(t UUID)
RETURNS SETOF UUID LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT DISTINCT u FROM (
    SELECT user_id AS u FROM task_assignments WHERE task_id = t
    UNION SELECT created_by FROM tasks WHERE id = t
    UNION SELECT a.user_id FROM tasks x JOIN task_assignments a ON a.task_id = x.parent_task_id WHERE x.id = t
    UNION SELECT o.user_id FROM tasks x JOIN effective_channel_owners o ON o.channel_id = x.channel_id WHERE x.id = t
    UNION SELECT o.user_id FROM tasks x JOIN channels c ON c.id = x.channel_id JOIN effective_channel_owners o ON o.channel_id = c.parent_channel_id WHERE x.id = t
    UNION SELECT suggested_by FROM task_suggestions WHERE task_id = t
  ) w WHERE u IS NOT NULL;
$$;
GRANT EXECUTE ON FUNCTION public.task_watchers(UUID) TO authenticated, service_role;

-- Insert one notification per watcher (minus the actor), deduped within 10s
-- so a client that still inserts its own copy does not double up.
CREATE OR REPLACE FUNCTION public.notify_task(t UUID, kind TEXT, payload JSONB, actor UUID, only_users UUID[] DEFAULT NULL)
RETURNS VOID LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE r UUID; title TEXT;
BEGIN
  SELECT x.title INTO title FROM tasks x WHERE x.id = t;
  FOR r IN SELECT * FROM unnest(COALESCE(only_users, ARRAY(SELECT task_watchers(t)))) LOOP
    IF r IS NULL OR r = actor THEN CONTINUE; END IF;
    IF EXISTS (SELECT 1 FROM notifications n WHERE n.user_id = r AND n.task_id = t AND n.type::text = kind AND n.created_at > now() - interval '10 seconds') THEN CONTINUE; END IF;
    INSERT INTO notifications (user_id, task_id, type, payload)
    VALUES (r, t, kind::notification_type, payload || jsonb_build_object('task_title', title, 'actor_id', actor));
  END LOOP;
END; $$;

-- ---- comments ----
CREATE OR REPLACE FUNCTION public.trg_notify_comment() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM notify_task(NEW.task_id, 'comment', jsonb_build_object('comment_body', left(NEW.body, 140), 'commented_by', NEW.user_id), NEW.user_id);
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS task_comments_notify ON task_comments;
CREATE TRIGGER task_comments_notify AFTER INSERT ON task_comments FOR EACH ROW EXECUTE FUNCTION trg_notify_comment();

-- ---- checklist ----
CREATE OR REPLACE FUNCTION public.trg_notify_checklist() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM notify_task(NEW.task_id, 'checklist', jsonb_build_object('item', left(NEW.body, 120), 'action', 'added'), COALESCE(auth.uid(), NEW.created_by));
  ELSIF NEW.is_done IS DISTINCT FROM OLD.is_done THEN
    PERFORM notify_task(NEW.task_id, 'checklist', jsonb_build_object('item', left(NEW.body, 120), 'action', CASE WHEN NEW.is_done THEN 'done' ELSE 'reopened' END), COALESCE(auth.uid(), NEW.done_by));
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS checklist_items_notify ON checklist_items;
CREATE TRIGGER checklist_items_notify AFTER INSERT OR UPDATE ON checklist_items FOR EACH ROW EXECUTE FUNCTION trg_notify_checklist();

-- ---- tasks: created (sub-task under a parent, or on a channel you own) + edited ----
CREATE OR REPLACE FUNCTION public.trg_notify_task_insert() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF NEW.parent_task_id IS NOT NULL THEN
    PERFORM notify_task(NEW.parent_task_id, 'subtask_added', jsonb_build_object('subtask_id', NEW.id, 'subtask_title', NEW.title), COALESCE(auth.uid(), NEW.created_by));
  ELSE
    -- channel owners hear about new work on their board
    PERFORM notify_task(NEW.id, 'task_created', jsonb_build_object('channel_id', NEW.channel_id), COALESCE(auth.uid(), NEW.created_by));
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS tasks_notify_insert ON tasks;
CREATE TRIGGER tasks_notify_insert AFTER INSERT ON tasks FOR EACH ROW EXECUTE FUNCTION trg_notify_task_insert();

-- Re-declare the 019 history trigger so one UPDATE also produces one
-- 'task_edited' notification listing the changed fields (status excluded:
-- the client already sends 'status_change').
CREATE OR REPLACE FUNCTION public.log_task_edit()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  f TEXT; changed TEXT[] := '{}';
  fields TEXT[] := ARRAY['title','description','priority','status','due_date','channel_id','parent_task_id',
                         'budget_allocated','budget_period_id','campaign_id','result_url','blocked_reason','blocked_by_email',
                         'planning_fields','tracker_fields'];
  o JSONB := to_jsonb(OLD); n JSONB := to_jsonb(NEW);
BEGIN
  FOREACH f IN ARRAY fields LOOP
    IF (o -> f) IS DISTINCT FROM (n -> f) THEN
      IF f = 'status' THEN CONTINUE; END IF;
      INSERT INTO activity_log (task_id, actor_id, action, from_value, to_value)
      VALUES (NEW.id, auth.uid(), 'edited', jsonb_build_object('field', f, 'value', o -> f), jsonb_build_object('field', f, 'value', n -> f));
      changed := changed || f;
    END IF;
  END LOOP;
  IF array_length(changed, 1) > 0 THEN
    PERFORM notify_task(NEW.id, 'task_edited', jsonb_build_object('fields', to_jsonb(changed)), auth.uid());
  END IF;
  RETURN NEW;
END; $$;

-- ---- suggestions ----
CREATE OR REPLACE FUNCTION public.trg_notify_suggestion() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  IF TG_OP = 'INSERT' THEN
    PERFORM notify_task(NEW.task_id, 'suggestion', jsonb_build_object('suggestion_id', NEW.id, 'fields', (SELECT to_jsonb(array_agg(k)) FROM jsonb_object_keys(NEW.patch) k), 'note', NEW.note), NEW.suggested_by);
  ELSIF NEW.status <> OLD.status AND NEW.status IN ('accepted', 'rejected') THEN
    PERFORM notify_task(NEW.task_id, 'suggestion_resolved', jsonb_build_object('suggestion_id', NEW.id, 'result', NEW.status), COALESCE(auth.uid(), NEW.resolved_by), ARRAY[NEW.suggested_by]);
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS task_suggestions_notify ON task_suggestions;
CREATE TRIGGER task_suggestions_notify AFTER INSERT OR UPDATE ON task_suggestions FOR EACH ROW EXECUTE FUNCTION trg_notify_suggestion();

-- ---- assignments: "somebody asks you for a task" ----
CREATE OR REPLACE FUNCTION public.trg_notify_assignment() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
BEGIN
  PERFORM notify_task(NEW.task_id, 'assigned', jsonb_build_object('role', NEW.role, 'assigned_by', NEW.assigned_by), COALESCE(auth.uid(), NEW.assigned_by), ARRAY[NEW.user_id]);
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS task_assignments_notify ON task_assignments;
CREATE TRIGGER task_assignments_notify AFTER INSERT ON task_assignments FOR EACH ROW EXECUTE FUNCTION trg_notify_assignment();

-- ---- thunderclap: you have been asked to do something ----
CREATE OR REPLACE FUNCTION public.trg_notify_participant() RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE c RECORD;
BEGIN
  IF NEW.user_id IS NULL THEN RETURN NEW; END IF;
  SELECT name, ask, kind INTO c FROM campaigns WHERE id = NEW.campaign_id;
  IF auth.uid() IS DISTINCT FROM NEW.user_id THEN
    INSERT INTO notifications (user_id, task_id, type, payload)
    VALUES (NEW.user_id, NULL, 'campaign_ask'::notification_type, jsonb_build_object('campaign_id', NEW.campaign_id, 'campaign_name', c.name, 'ask', c.ask, 'kind', c.kind));
  END IF;
  RETURN NEW;
END; $$;
DROP TRIGGER IF EXISTS campaign_participants_notify ON campaign_participants;
CREATE TRIGGER campaign_participants_notify AFTER INSERT ON campaign_participants FOR EACH ROW EXECUTE FUNCTION trg_notify_participant();

-- Users may delete their own notifications (clear list).
DROP POLICY IF EXISTS "notifications_delete" ON notifications;
CREATE POLICY "notifications_delete" ON notifications FOR DELETE TO authenticated USING (auth.uid() = user_id);

-- ############################################################
-- 021_auth_providers.sql
-- ############################################################
-- ============================================================
-- Migration 021: sign-in with Slack or Microsoft as well as Google.
--  * profile name / avatar read from whatever the provider sends
--    (Google: full_name + avatar_url; Slack: name + picture; Microsoft: name)
--  * only Lyzr accounts may sign in (lyzr.ai or lyzr.com); anyone else is
--    rejected at the database, whatever the provider
--  * name@lyzr.ai and name@lyzr.com are the same person: owner rows,
--    pending assignments and badges written with either spelling attach
-- Idempotent; safe to paste on the live DB.
-- ============================================================

CREATE OR REPLACE FUNCTION public.lyzr_twin(e TEXT)
RETURNS TEXT LANGUAGE sql IMMUTABLE AS $$
  SELECT CASE
    WHEN lower(e) LIKE '%@lyzr.ai'  THEN regexp_replace(lower(e), '@lyzr\.ai$',  '@lyzr.com')
    WHEN lower(e) LIKE '%@lyzr.com' THEN regexp_replace(lower(e), '@lyzr\.com$', '@lyzr.ai')
    ELSE lower(e) END;
$$;

CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  em   TEXT := lower(NEW.email);
  twin TEXT := lyzr_twin(NEW.email);
  md   JSONB := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb);
  nm   TEXT;
  av   TEXT;
BEGIN
  IF em IS NULL OR NOT (em LIKE '%@lyzr.ai' OR em LIKE '%@lyzr.com') THEN
    RAISE EXCEPTION 'Only Lyzr accounts can sign in to the tracker (%)', em USING ERRCODE = '42501';
  END IF;

  nm := COALESCE(NULLIF(md->>'full_name', ''), NULLIF(md->>'name', ''), NULLIF(md->>'preferred_username', ''), split_part(em, '@', 1));
  av := COALESCE(NULLIF(md->>'avatar_url', ''), NULLIF(md->>'picture', ''));

  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (
    NEW.id, NEW.email, nm, av,
    CASE WHEN EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) IN (em, twin))
         THEN 'admin'::user_role ELSE 'member'::user_role END
  );

  UPDATE pending_mentions SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id FROM pending_mentions pm
   WHERE lower(pm.email) IN (em, twin) AND pm.resolved_user_id = NEW.id;
  UPDATE pending_invites SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE WHEN pa.role = 'primary' AND EXISTS (SELECT 1 FROM task_assignments ta WHERE ta.task_id = pa.task_id AND ta.role = 'primary')
              THEN 'secondary'::assignment_role ELSE pa.role END,
         pa.assigned_by
    FROM pending_assignments pa WHERE lower(pa.email) IN (em, twin) AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;
  UPDATE pending_assignments SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  UPDATE channel_owners        SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_members      SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE function_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  RETURN NEW;
END;
$$;

-- Leadership / admin lookups by either spelling.
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM users WHERE id = auth.uid() AND role = 'admin');
$$;

-- Backfill: people already signed in get names/avatars refreshed from the
-- provider metadata if the profile is still the bare email prefix.
UPDATE users u SET
  display_name = COALESCE(NULLIF(a.raw_user_meta_data->>'full_name',''), NULLIF(a.raw_user_meta_data->>'name',''), u.display_name),
  avatar_url   = COALESCE(u.avatar_url, NULLIF(a.raw_user_meta_data->>'avatar_url',''), NULLIF(a.raw_user_meta_data->>'picture',''))
FROM auth.users a WHERE a.id = u.id;

-- ############################################################
-- 022_one_person_two_emails.sql
-- ############################################################
-- ============================================================
-- Migration 022: one person, two emails (name@lyzr.ai + name@lyzr.com).
-- A person has ONE tracker account. Extra sign-in methods are attached to it
-- with Supabase "manual linking" (Me › Linked accounts), never as a second
-- user. If someone tries to sign up with a provider whose email is the twin
-- of an existing account, sign-up is refused with a message telling them to
-- link instead. `link_my_emails()` re-attaches owner / member / badge rows
-- written under either spelling and records the second email on the profile.
-- Idempotent; safe to paste on the live DB. Run AFTER 021.
-- ============================================================

ALTER TABLE users ADD COLUMN IF NOT EXISTS alt_email TEXT;

-- Refuse a duplicate account for the twin address.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  em   TEXT := lower(NEW.email);
  twin TEXT := lyzr_twin(NEW.email);
  md   JSONB := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb);
  nm   TEXT;
  av   TEXT;
  existing TEXT;
BEGIN
  IF em IS NULL OR NOT (em LIKE '%@lyzr.ai' OR em LIKE '%@lyzr.com') THEN
    RAISE EXCEPTION 'Only Lyzr accounts can sign in to the tracker (%)', em USING ERRCODE = '42501';
  END IF;
  SELECT email INTO existing FROM public.users WHERE lower(email) = twin OR lower(alt_email) = em LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'You already have a tracker account as %. Sign in with that one, then add this login under Me › Linked accounts.', existing USING ERRCODE = '42501';
  END IF;

  nm := COALESCE(NULLIF(md->>'full_name', ''), NULLIF(md->>'name', ''), NULLIF(md->>'preferred_username', ''), split_part(em, '@', 1));
  av := COALESCE(NULLIF(md->>'avatar_url', ''), NULLIF(md->>'picture', ''));
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (NEW.id, NEW.email, nm, av,
    CASE WHEN EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) IN (em, twin)) THEN 'admin'::user_role ELSE 'member'::user_role END);
  UPDATE pending_mentions SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id FROM pending_mentions pm WHERE lower(pm.email) IN (em, twin) AND pm.resolved_user_id = NEW.id;
  UPDATE pending_invites SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id,
         CASE WHEN pa.role = 'primary' AND EXISTS (SELECT 1 FROM task_assignments ta WHERE ta.task_id = pa.task_id AND ta.role = 'primary') THEN 'secondary'::assignment_role ELSE pa.role END,
         pa.assigned_by
    FROM pending_assignments pa WHERE lower(pa.email) IN (em, twin) AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;
  UPDATE pending_assignments SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  UPDATE channel_owners        SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_members      SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE function_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_owners       SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  RETURN NEW;
END;
$$;

-- Called by the app after every sign-in and after linking a provider:
-- gathers every email on the auth account (all linked identities), stores
-- the second spelling on the profile, and attaches rows written under any
-- of them. Also resolves pending assignments left for the other spelling.
CREATE OR REPLACE FUNCTION public.link_my_emails()
RETURNS JSONB LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  me UUID := auth.uid();
  emails TEXT[];
  main TEXT;
  n INT := 0; c INT;
BEGIN
  IF me IS NULL THEN RETURN '{}'::jsonb; END IF;
  SELECT lower(email) INTO main FROM public.users WHERE id = me;
  SELECT array_agg(DISTINCT e) INTO emails FROM (
    SELECT lower(i.identity_data->>'email') AS e FROM auth.identities i WHERE i.user_id = me AND i.identity_data->>'email' IS NOT NULL
    UNION SELECT main
    UNION SELECT lyzr_twin(main)
  ) x WHERE e IS NOT NULL;

  UPDATE public.users SET alt_email = (SELECT e FROM unnest(emails) e WHERE e <> main AND (e LIKE '%@lyzr.ai' OR e LIKE '%@lyzr.com') LIMIT 1) WHERE id = me;

  UPDATE channel_owners        SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE vertical_owners       SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE vertical_members      SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE function_owners       SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE campaign_owners       SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE campaign_participants SET user_id = me WHERE lower(email) = ANY(emails) AND user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, me,
         CASE WHEN pa.role = 'primary' AND EXISTS (SELECT 1 FROM task_assignments ta WHERE ta.task_id = pa.task_id AND ta.role = 'primary') THEN 'secondary'::assignment_role ELSE pa.role END,
         pa.assigned_by
    FROM pending_assignments pa WHERE lower(pa.email) = ANY(emails) AND pa.resolved_user_id IS NULL
  ON CONFLICT (task_id, user_id) DO NOTHING;
  UPDATE pending_assignments SET resolved_user_id = me, resolved_at = now() WHERE lower(email) = ANY(emails) AND resolved_user_id IS NULL; GET DIAGNOSTICS c = ROW_COUNT; n := n + c;
  UPDATE public.users SET role = 'admin' WHERE id = me AND role <> 'admin' AND EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) = ANY(emails));
  RETURN jsonb_build_object('emails', to_jsonb(emails), 'linked_rows', n);
END;
$$;
GRANT EXECUTE ON FUNCTION public.link_my_emails() TO authenticated;

-- Badge lookups accept either spelling of the person's addresses.
CREATE OR REPLACE FUNCTION public.is_admin()
RETURNS BOOLEAN LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$
  SELECT EXISTS (SELECT 1 FROM users WHERE id = auth.uid() AND role = 'admin');
$$;

-- ############################################################
-- 023_com_only.sql
-- ############################################################
-- ============================================================
-- Migration 023: Microsoft only, lyzr.com only (per Kailash 2026-09-26).
--  * every stored lyzr.ai address becomes its lyzr.com twin (owners,
--    members, badges, pending rows, profiles, auth accounts)
--  * sign-up accepts lyzr.com only
--  * existing accounts keep their id (tasks/history stay attached) but now
--    carry the .com address, so the Microsoft login lands on them
-- Idempotent; safe to paste on the live DB. Run AFTER 022.
-- ============================================================

-- 1. Badges: keep the .com spelling only.
INSERT INTO admin_emails (email) SELECT lyzr_twin(email) FROM admin_emails WHERE email LIKE '%@lyzr.ai' ON CONFLICT DO NOTHING;
DELETE FROM admin_emails WHERE email LIKE '%@lyzr.ai';
INSERT INTO leadership_emails (email) SELECT lyzr_twin(email) FROM leadership_emails WHERE email LIKE '%@lyzr.ai' ON CONFLICT DO NOTHING;
DELETE FROM leadership_emails WHERE email LIKE '%@lyzr.ai';

-- 2. Ownership / membership rows: rewrite .ai -> .com, dropping a .ai row
--    when the .com twin already exists on the same key.
DELETE FROM channel_owners a USING channel_owners b WHERE a.email LIKE '%@lyzr.ai' AND b.channel_id = a.channel_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE channel_owners SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
DELETE FROM vertical_owners a USING vertical_owners b WHERE a.email LIKE '%@lyzr.ai' AND b.vertical_id = a.vertical_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE vertical_owners SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
DELETE FROM vertical_members a USING vertical_members b WHERE a.email LIKE '%@lyzr.ai' AND b.vertical_id = a.vertical_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE vertical_members SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
DELETE FROM function_owners a USING function_owners b WHERE a.email LIKE '%@lyzr.ai' AND b.function_id = a.function_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE function_owners SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
DELETE FROM campaign_owners a USING campaign_owners b WHERE a.email LIKE '%@lyzr.ai' AND b.campaign_id = a.campaign_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE campaign_owners SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
DELETE FROM campaign_participants a USING campaign_participants b WHERE a.email LIKE '%@lyzr.ai' AND b.campaign_id = a.campaign_id AND lower(b.email) = lyzr_twin(a.email);
UPDATE campaign_participants SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
UPDATE pending_assignments SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
UPDATE pending_invites     SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
UPDATE pending_mentions    SET email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';

-- 3. Accounts: same id, .com address. The Microsoft login then matches them.
UPDATE public.users SET alt_email = email, email = lyzr_twin(email) WHERE email LIKE '%@lyzr.ai';
UPDATE auth.users
   SET email = lyzr_twin(email),
       raw_user_meta_data = coalesce(raw_user_meta_data, '{}'::jsonb) || jsonb_build_object('email', lyzr_twin(email))
 WHERE email LIKE '%@lyzr.ai';

-- 4. Sign-up: lyzr.com only.
CREATE OR REPLACE FUNCTION handle_new_user()
RETURNS TRIGGER LANGUAGE plpgsql SECURITY DEFINER SET search_path = public AS $$
DECLARE
  em TEXT := lower(NEW.email); twin TEXT := lyzr_twin(NEW.email); md JSONB := COALESCE(NEW.raw_user_meta_data, '{}'::jsonb); nm TEXT; av TEXT; existing TEXT;
BEGIN
  IF em IS NULL OR em NOT LIKE '%@lyzr.com' THEN
    RAISE EXCEPTION 'Only lyzr.com Microsoft accounts can sign in to the tracker (%)', em USING ERRCODE = '42501';
  END IF;
  SELECT email INTO existing FROM public.users WHERE lower(email) = twin OR lower(alt_email) = em LIMIT 1;
  IF existing IS NOT NULL THEN
    RAISE EXCEPTION 'You already have a tracker account as %. Ask an admin to move it to your lyzr.com address.', existing USING ERRCODE = '42501';
  END IF;
  nm := COALESCE(NULLIF(md->>'full_name', ''), NULLIF(md->>'name', ''), NULLIF(md->>'preferred_username', ''), split_part(em, '@', 1));
  av := COALESCE(NULLIF(md->>'avatar_url', ''), NULLIF(md->>'picture', ''));
  INSERT INTO public.users (id, email, display_name, avatar_url, role)
  VALUES (NEW.id, NEW.email, nm, av, CASE WHEN EXISTS (SELECT 1 FROM admin_emails a WHERE lower(a.email) IN (em, twin)) THEN 'admin'::user_role ELSE 'member'::user_role END);
  UPDATE pending_mentions SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO mentions (task_id, surface, surface_ref_id, mentioned_user_id, mentioned_email, mentioned_by)
  SELECT pm.task_id, pm.surface, pm.surface_ref_id, NEW.id, NEW.email, NEW.id FROM pending_mentions pm WHERE lower(pm.email) IN (em, twin) AND pm.resolved_user_id = NEW.id;
  UPDATE pending_invites SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  INSERT INTO task_assignments (task_id, user_id, role, assigned_by)
  SELECT pa.task_id, NEW.id, CASE WHEN pa.role = 'primary' AND EXISTS (SELECT 1 FROM task_assignments ta WHERE ta.task_id = pa.task_id AND ta.role = 'primary') THEN 'secondary'::assignment_role ELSE pa.role END, pa.assigned_by
    FROM pending_assignments pa WHERE lower(pa.email) IN (em, twin) AND pa.resolved_user_id IS NULL ON CONFLICT (task_id, user_id) DO NOTHING;
  UPDATE pending_assignments SET resolved_user_id = NEW.id, resolved_at = now() WHERE lower(email) IN (em, twin) AND resolved_user_id IS NULL;
  UPDATE channel_owners SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_owners SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE vertical_members SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE function_owners SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_owners SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  UPDATE campaign_participants SET user_id = NEW.id WHERE lower(email) IN (em, twin) AND user_id IS NULL;
  RETURN NEW;
END; $$;

-- 5. What to check afterwards (returns one row).
SELECT
  (SELECT count(*) FROM auth.users WHERE email LIKE '%@lyzr.ai')            AS auth_ai_left,
  (SELECT string_agg(email, ', ') FROM auth.users)                            AS auth_emails,
  (SELECT string_agg(email || ' [' || role || ']', ', ') FROM public.users)   AS profiles,
  (SELECT string_agg(email, ', ') FROM admin_emails)                          AS admins,
  (SELECT count(*) FROM vertical_owners WHERE email LIKE '%@lyzr.ai')         AS owner_rows_ai_left;

-- ---------- POST: re-mirror existing auth accounts ----------
-- handle_new_user only fires on INSERT into auth.users, so anyone who signed
-- in before this reset must be backfilled into public.users here.
INSERT INTO public.users (id, email, display_name, avatar_url, role)
SELECT id, email,
       COALESCE(raw_user_meta_data->>'full_name', split_part(email, '@', 1)),
       raw_user_meta_data->>'avatar_url',
       CASE WHEN email = 'kailash.gm@lyzr.ai' THEN 'admin'::user_role ELSE 'member'::user_role END
FROM auth.users
ON CONFLICT (id) DO NOTHING;

-- Belt-and-braces: make sure PostgREST roles can reach everything created above.
GRANT ALL ON ALL TABLES    IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL ROUTINES  IN SCHEMA public TO anon, authenticated, service_role;
GRANT ALL ON ALL SEQUENCES IN SCHEMA public TO anon, authenticated, service_role;

-- ---------- SANITY CHECK ----------
SELECT 'tables' AS what, count(*)::text AS value FROM information_schema.tables WHERE table_schema = 'public'
UNION ALL SELECT 'users mirrored', count(*)::text FROM public.users
UNION ALL SELECT 'verticals (expect 0 until seed)', count(*)::text FROM verticals
UNION ALL SELECT 'categories (expect 0 until seed)', count(*)::text FROM categories
UNION ALL SELECT 'functions (expect 12)', count(*)::text FROM functions
UNION ALL SELECT 'admin present', count(*)::text FROM public.users WHERE role = 'admin';
